} from './wi-select.types';
import { WiIconComponent } from '@wiloc/ui/icon';

const TRIGGER_BASE_CLASSES = [
  'wi-select__trigger',
  'flex',
  'w-full',
  'min-w-0',
  'items-center',
  'justify-between',
  'gap-2',
