    WiIconComponent,
    BrnSelect,
    BrnSelectMultiple,
    BrnSelectTrigger,
    BrnSelectContent,
    BrnSelectList,
    BrnSelectItem,
    BrnPopover,
    BrnPopoverContent,
  ],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => WiSelectComponent),
      multi: true,
    },
    provideBrnPopoverConfig({
      align: 'start',
